SCREENS['lu-inventory'] = () => {
  const fR = ui('luRole', 'all'), fT = ui('luType', 'records'), fC = ui('luComp', 'any');
  const roles = [...new Set(LU_ROWS.flatMap(r => r[1].split(', ')))];
  const isRec = r => ['Work queue', 'History', 'Reference'].includes(r[8]);
  const keep = r => (fR === 'all' || r[1].split(', ').includes(fR)) && (fT === 'all' || (fT === 'records' ? isRec(r) : r[8] === fT)) && (fC === 'any' || r[4] === fC);
  const list = LU_ROWS.filter(keep);
  const rec = LU_ROWS.filter(isRec), cnt = f => rec.filter(f).length;
  const sel = (id, k, label, opts, cur) => `<div class="field"><label for="${id}">${label}</label><select class="select" id="${id}" data-onchange="luF" data-k="${k}">${opts.map(([v, l]) => `<option value="${esc(v)}" ${cur === v ? 'selected' : ''}>${esc(l)}</option>`).join('')}</select></div>`;
  const th = cols => `<thead><tr>${cols.map(c => `<th scope="col">${c}</th>`).join('')}</tr></thead>`;
  return `${pageHead('List Upgrade — Inventory', `Step 1 of the list upgrade. Every list and table in every view, with the proposed date field, list type and default sort. Nothing has been changed yet. Captured ${LU_SCAN.date} by rendering ${LU_SCAN.routes} screens and tabs across ${LU_SCAN.roles} role views.`)}
  <section class="card"><h2>Summary</h2>
    <div class="ux-kpis"><div><strong>${rec.length}</strong><span>record lists</span></div><div><strong>${cnt(r => r[4] === 'Yes but search off')}</strong><span>shared, search off</span></div><div><strong>${cnt(r => r[4] === 'No (custom)')}</strong><span>custom, to migrate</span></div><div><strong>${cnt(r => r[8] === 'Work queue')}</strong><span>work queues (order kept)</span></div><div><strong>${cnt(r => r[8] === 'History')}</strong><span>history (newest first)</span></div><div><strong>${LU_RISKS.length}</strong><span>risks to review</span></div></div>
    <p class="small">How this was captured: each role was signed in, then every sidebar item, every sub-tab and the first detail page (with its tabs) was rendered. Shared-component tables were read from the component's own configuration (columns, search, filters, page size, export, row dates). Other tables and lists were read from the rendered page. "Current sort" is the order the rows arrive in: the shared component has no default sort today.</p>
    <p class="small muted">Not lists, so not counted: ${LU_ROWS.length - rec.length} dashboard widgets, summaries, matrices and forms (choose "All" under List type to see them). Workplace Contact and Verification pages have no record lists apart from the demo inbox, which is out of scope.</p>
  </section>
  <section class="card"><h2>Risks and decisions before Step 2</h2><div class="tbl-wrap"><table class="tbl dense ux-tbl">${th(['ID', 'Area', 'Finding', 'Proposal'])}<tbody>${LU_RISKS.map(r => `<tr><td class="strong nowrap">${r[0]}</td><td class="small nowrap">${esc(r[1])}</td><td class="small">${esc(r[2])}</td><td class="small">${esc(r[3])}</td></tr>`).join('')}</tbody></table></div></section>
  <section class="card"><div class="ux-filt">${sel('lu-r', 'luRole', 'Role view', [['all', 'All roles']].concat(roles.map(r => [r, r])), fR)}${sel('lu-t', 'luType', 'List type', [['records', 'Record lists (work queue, history, reference)'], ['Work queue', 'Work queue'], ['History', 'History'], ['Reference', 'Reference'], ['Dashboard widget', 'Dashboard widget'], ['Summary / matrix', 'Summary / matrix'], ['all', 'All']], fT)}${sel('lu-c', 'luComp', 'Shared component?', [['any', 'Any'], ['Yes', 'Yes'], ['Yes but search off', 'Yes but search off'], ['No (custom)', 'No (custom)']], fC)}<p class="small muted" role="status">Showing ${list.length} of ${LU_ROWS.length} rows</p></div></section>
  <section class="card"><h2>Lists and tables</h2><div class="tbl-wrap"><table class="tbl dense ux-tbl">${th(['View / route', 'List name', 'Shared component?', 'Search?', 'Date columns', 'Default date field', 'List type', 'Current default sort', 'Proposed default sort', 'Export?', 'Risk notes'])}<tbody>${list.map(r => `<tr><td class="small"><strong>${esc(r[1])}</strong><br><span class="mono xs">${esc(r[2])}</span></td><td class="small">${esc(r[3])}<br><span class="xs muted">${r[13]} rows in demo</span></td><td class="small nowrap">${r[4] === 'Yes' ? chip('Yes', 'green') : r[4] === 'No (custom)' ? chip('No (custom)', 'red') : chip('Search off', 'amber')}</td><td class="small">${esc(r[5])}</td><td class="small">${esc(r[6])}</td><td class="small">${esc(r[7])}</td><td class="small nowrap">${chip(r[8], LU_TYPE_TONE[r[8]])}</td><td class="small">${esc(r[9])}</td><td class="small">${esc(r[10])}</td><td class="small">${esc(r[11])}</td><td class="small">${esc(r[12])}</td></tr>`).join('') || '<tr><td colspan="11" class="small muted">No rows for these filters.</td></tr>'}</tbody></table></div></section>
  <section class="card"><h2>Calendars</h2><div class="tbl-wrap"><table class="tbl dense ux-tbl">${th(['Role', 'Route', 'Screen', 'Navigation today', 'Planned (Part B)', 'Notes'])}<tbody>${LU_CAL.map(c => `<tr><td class="small strong">${esc(c[0])}</td><td class="small mono">${esc(c[1])}</td><td class="small">${esc(c[2])}</td><td class="small">${esc(c[3])}</td><td class="small">${esc(c[4])}</td><td class="small">${esc(c[5])}</td></tr>`).join('')}</tbody></table></div></section>
  <section class="card"><h2>Notifications pages (B4)</h2><div class="tbl-wrap"><table class="tbl dense ux-tbl">${th(['Role', 'Route', 'Filters today', 'Items in demo'])}<tbody>${LU_NOTIF.map(n => `<tr><td class="small strong">${esc(n[0])}</td><td class="small mono">${esc(n[1])}</td><td class="small">${esc(n[2])}</td><td class="small">${esc(n[3])}</td></tr>`).join('')}</tbody></table></div><p class="small muted">None has search, date grouping, an Unread filter (except the learner "Unread" tab and category "Unread" options) or "Load older". Header bell dropdowns stay as they are.</p></section>
  <section class="card"><h2>Messages screens (B5)</h2><div class="tbl-wrap"><table class="tbl dense ux-tbl">${th(['Role', 'Route', 'Threads in demo', 'Search today', 'Thread status exists'])}<tbody>${LU_MSG.map(m => `<tr><td class="small strong">${esc(m[0])}</td><td class="small mono">${esc(m[1])}</td><td class="small num">${m[2]}</td><td class="small">${m[3]}</td><td class="small">${esc(m[4])}</td></tr>`).join('')}</tbody></table></div><p class="small muted">The thread-list order today is checked per screen at Step 2; B5.3 only changes it where it isn't already latest activity first.</p></section>
  <section class="card"><h2>Learner Attendance (B6)</h2><p class="small">Route <span class="mono">attendance</span>. A custom table: Session, Date, Duration, Status, Time attended, Recorded. No filters, no paging, all sessions in data order, KPI tiles for overall attendance. The "learner visibility not specified in SRS" TBD stays. Planned: course filter, month + year selector, the B1.2 date filter, newest first, and a summary line that follows the filters.</p></section>`;
};
INP.luF = el => { setUi(el.dataset.k, el.value); render(); };

const _idxLU = SCREENS.index;
SCREENS.index = p => _idxLU(p) + `<section class="card idx-sec"><h2>List upgrade</h2><ul class="idx-list"><li><button class="linklike" data-go="lu-inventory">List Upgrade — Inventory</button> <span class="xs muted">· Step 1: every list and table, list type, date field, sort, risks</span></li></ul></section>`;
